-- Rollback-only adversarial checks. Test clock/owners are privileged fixtures.
begin;
create function pg_temp.p15_fails(q text,expected text) returns boolean language plpgsql as $$
begin execute q; return false; exception when others then
  if sqlstate<>expected then raise notice 'Unexpected %: %',sqlstate,sqlerrm; end if;
  return sqlstate=expected;
end $$;
do $$
declare a uuid; b uuid; c uuid; d uuid; e uuid; ep uuid; m uuid; t uuid; t2 uuid; solo uuid; x uuid; sub uuid; cs uuid;
  ma uuid; mb uuid; mc uuid; draft uuid; objection uuid; synthesis uuid; mf jsonb; j jsonb; h text; original text; n bigint; r record;
  nonce text:=repeat('1',64);
begin
  assert public.trust_status()->>'permissionless'='false','future stages fail closed';
  assert public.trust_status()->>'custody'='test_units','no custody claim';
  mf:='{"schema_version":1,"lab":"p15-fixture","models":["fixture"],"capabilities":["analysis"],"tools":[],"languages":["en"],"context_window":32000,"strengths":[],"roles":["proposer","critic","synthesizer"]}';
  a:=(public.register_manifest_agent('198.18.15.1','p15-a',p_manifest=>mf)->'agent'->>'id')::uuid;
  b:=(public.register_manifest_agent('198.18.15.2','p15-b',p_manifest=>mf)->'agent'->>'id')::uuid;
  c:=(public.register_manifest_agent('198.18.15.3','p15-c',p_manifest=>mf)->'agent'->>'id')::uuid;
  d:=(public.register_manifest_agent('198.18.15.4','p15-d',p_manifest=>mf)->'agent'->>'id')::uuid;
  assert pg_temp.p15_fails(format('select public.trust_enroll(%L)',a),'PT403'),'unclaimed enrollment refused';
  -- A distinct existing profile represents each already-attested owner.
  insert into auth.users(id,email) values(gen_random_uuid(),'p15a@fixture.invalid') returning id into x;
  update public.agents set owner_id=x where id=a;
  insert into auth.users(id,email) values(gen_random_uuid(),'p15b@fixture.invalid') returning id into x;
  update public.agents set owner_id=x where id=b;
  insert into auth.users(id,email) values(gen_random_uuid(),'p15c@fixture.invalid') returning id into x;
  update public.agents set owner_id=x where id=c;
  assert pg_temp.p15_fails(format('select public.trust_enroll(%L)',a),'PT409'),'epoch declaration required';
  insert into public.trust_epochs(starts_at,ends_at,stake_units,escrow_units,dispute_seconds,reward_cap,operator,reason)
    values(now()-interval '1 day',now()+interval '1 day',100,60,60,5,'local-auditor','Privileged local test clock fixture') returning id into ep;
  assert pg_temp.p15_fails(format('update public.trust_epochs set stake_units=1 where id=%L',ep),'PT403'),'no mid-epoch parameter edits';
  assert pg_temp.p15_fails(format('select public.declare_trust_epoch(%L,%L,100,60,60,5,%L,%L)',now()+interval '1 hour',now()+interval '2 days','local-auditor','Attempt overlapping declaration'),'PT409'),'epochs cannot overlap';
  assert pg_temp.p15_fails(format('select public.declare_trust_epoch(%L,%L,100,60,60,5,%L,%L)',now()-interval '1 day',now()+interval '2 days','local-auditor','Attempt retroactive declaration'),'PT400'),'no retroactive epochs';
  perform public.trust_enroll(a); perform public.trust_enroll(b); perform public.trust_enroll(c);
  perform public.trust_enroll(a);
  assert (select count(*)=1 from public.trust_events where agent_id=a),'enrollment retry is idempotent';
  perform public.credit_trust_test_units(a,100,'p15-receipt-a','local-auditor');
  perform public.credit_trust_test_units(a,100,'p15-receipt-a','local-auditor');
  assert (select balance=100 from public.trust_accounts where agent_id=a),'receipt cannot mint twice';
  assert pg_temp.p15_fails(format('select public.credit_trust_test_units(%L,100,%L,%L)',b,'p15-receipt-a','local-auditor'),'PT409'),'receipt cannot cross identities';
  perform public.credit_trust_test_units(b,100,'p15-receipt-b','local-auditor');
  perform public.credit_trust_test_units(c,100,'p15-receipt-c','local-auditor');
  assert not exists(select 1 from public.reputation_events where agent_id=any(array[a,b,c])),'stake never buys reputation';
  insert into public.missions(slug,title,objective,status,created_by_agent,lead_agent_id,review_quorum,requires_final_approval)
    values('p15-contract','Closed testnet contract','Exercise opt-in trust controls','active',a,a,1,false) returning id into m;
  t:=public.insert_task_from_json(m,'{"key":"sealed","title":"Sealed ensemble","kind":"analysis","capabilities":["analysis"],"ensemble":{"distinct_labs":false,"roles":[{"role":"proposer"},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  select id into e from public.ensembles where task_id=t;
  perform public.bind_trust_task(t);
  assert pg_temp.p15_fails(format('select public.bind_trust_task(%L,false)',t),'PT409'),'regime immutable';
  assert pg_temp.p15_fails(format('select public.ensemble_join(%L,%L,%L)',d,e,'proposer'),'PT409'),'unenrolled role refused';
  ma:=(public.ensemble_join(a,e,'proposer')->>'id')::uuid;
  mb:=(public.ensemble_join(b,e,'critic')->>'id')::uuid;
  mc:=(public.ensemble_join(c,e,'synthesizer')->>'id')::uuid;
  perform public.ensemble_join(a,e,'proposer');
  assert (select count(*)=1 from public.trust_escrows where agent_id=a),'renewal reserves once';
  assert (select sum(units)=180 from public.trust_escrows where task_id=t),'each role has distinct exposure';
  solo:=public.insert_task_from_json(m,'{"key":"escrow","title":"Second concurrent assignment","kind":"analysis","capabilities":["analysis"]}','open');
  perform public.bind_trust_task(solo,false);
  assert pg_temp.p15_fails(format('select public.claim_task(%L,%L)',a,solo),'PT409'),'encumbered stake cannot be reused';
  assert (select status='open' and assignee_id is null from public.tasks where id=solo),'failed reservation rolls back claim';
  assert pg_temp.p15_fails(format('select public.ensemble_contribute(%L,%L,%L,%L,%L)',a,e,'draft','Publish before commit','Attempt to reveal early'),'PT409'),'ordinary contribution cannot bypass sealing';
  h:=public.sealed_text_digest(e,1,ma,'draft',' Proposal π ','First line'||chr(10)||'🧪',nonce);
  perform public.ensemble_commit(a,e,1,h);
  perform public.ensemble_commit(a,e,1,h);
  assert (select count(*)=1 from public.ensemble_commitments where ensemble_id=e),'commit retry idempotent';
  assert pg_temp.p15_fails(format('select public.ensemble_commit(%L,%L,1,%L)',a,e,repeat('a',64)),'PT409'),'cannot replace commitment';
  assert pg_temp.p15_fails(format('select public.ensemble_reveal(%L,%L,1,%L,%L,%L,%L)',a,e,'draft',' Proposal π ','First line'||chr(10)||'🧪',nonce),'PT409'),'all roles commit before first reveal';
  perform public.ensemble_commit(b,e,1,public.sealed_text_digest(e,1,mb,'objection','Boundary objection','Initial independent concern',nonce));
  perform public.ensemble_commit(c,e,1,public.sealed_text_digest(e,1,mc,'synthesis','Initial synthesis','Independent initial synthesis',nonce));
  assert pg_temp.p15_fails(format('select public.ensemble_reveal(%L,%L,1,%L,%L,%L,%L)',a,e,'draft','Changed proposal','First line'||chr(10)||'🧪',nonce),'PT400'),'changed bytes rejected';
  assert pg_temp.p15_fails(format('select public.ensemble_reveal(%L,%L,2,%L,%L,%L,%L)',a,e,'draft',' Proposal π ','First line'||chr(10)||'🧪',nonce),'PT409'),'stale round rejected';
  j:=public.ensemble_reveal(a,e,1,'draft',' Proposal π ','First line'||chr(10)||'🧪',nonce); draft:=(j->>'id')::uuid;
  assert public.ensemble_reveal(a,e,1,'draft',' Proposal π ','First line'||chr(10)||'🧪',nonce)->>'id'=draft::text,'reveal retry idempotent';
  assert pg_temp.p15_fails(format('select public.ensemble_score(%L,%L,5,%L)',b,draft,'Attempt scoring without revealing'),'PT403'),'withheld initial draft cannot score';
  assert pg_temp.p15_fails(format('select public.ensemble_contribute(%L,%L,%L,%L,%L)',a,e,'draft','Second draft','Observe all initial drafts first'),'PT409'),'deliberation waits for complete reveal';
  objection:=(public.ensemble_reveal(b,e,1,'objection','Boundary objection','Initial independent concern',nonce)->>'id')::uuid;
  perform public.ensemble_reveal(c,e,1,'synthesis','Initial synthesis','Independent initial synthesis',nonce);
  synthesis:=(public.ensemble_contribute(c,e,'synthesis','Final synthesis','Addresses every revealed draft and the boundary objection',objection)->>'id')::uuid;
  perform public.ensemble_score(b,draft,5,'Initial approach was independently considered');
  perform public.ensemble_score(a,objection,5,'The boundary concern was confirmed by the evidence');
  perform public.ensemble_score(a,synthesis,5,'Final synthesis addresses the committed evidence');
  perform public.ensemble_score(b,synthesis,5,'Critic explicitly checked the final synthesis');
  j:=public.ensemble_submit(c,e,synthesis,array[draft,objection,synthesis],jsonb_build_array(jsonb_build_object('contribution_id',objection,'upheld',true,'rationale','Final result explicitly handles the boundary concern')));
  sub:=(j->>'submission_id')::uuid;
  perform public.review_submission(sub,d,null,'approve',5,'Independently checked criteria and the committed objection','peer_review',jsonb_build_array(jsonb_build_object('objection_id',objection,'upheld',true,'passed',true)));
  assert (select status='accepted' from public.submissions where id=sub),'ordinary independent review still settles';
  assert (select sum(delta)<=5 from public.reputation_events where task_id=t and delta>0),'declared task reward cap holds';
  assert not exists(select 1 from public.trust_escrows where task_id=t and release_after is null),'settlement starts dispute window';
  assert (public.trust_release(a)->>'released_units')::bigint=0,'cannot release before dispute deadline';
  cs:=(public.open_trust_case(a,t,'correlation',repeat('a',64),'https://fixtures.invalid/p15-evidence','local-auditor')->>'id')::uuid;
  assert (select balance=100 and not frozen from public.trust_accounts where agent_id=a),'statistical flag does not auto-slash or demote';
  update public.trust_escrows set release_after=now()-interval '1 second' where task_id=t;
  assert pg_temp.p15_fails(format('select public.trust_release(%L)',a),'PT409'),'open dispute holds collateral';
  perform public.decide_trust_case(cs,true,40,'attested-reserve','Confirmed with independent attested evidence review');
  assert (select balance=60 and frozen from public.trust_accounts where agent_id=a),'confirmed evidence slashes and freezes';
  assert pg_temp.p15_fails(format('select public.decide_trust_case(%L,true,40,%L,%L)',cs,'attested-reserve','Attempt to replay the slash decision'),'PT409'),'decision cannot slash twice';
  assert pg_temp.p15_fails(format('select public.appeal_trust_case(%L,%L,%L)',b,cs,'Attempt appeal for another identity'),'PT404'),'appeals bound to identity';
  perform public.appeal_trust_case(a,cs,'The cited evidence has a reproducible confound');
  assert pg_temp.p15_fails(format('select public.trust_release(%L)',a),'PT409'),'pending appeal holds collateral';
  perform public.resolve_trust_appeal(cs,false,'appeal-reserve','Independent appeal found the correlation confound');
  assert (select balance=100 and not frozen from public.trust_accounts where agent_id=a),'overturned decision restores exact units';
  assert pg_temp.p15_fails(format('select public.resolve_trust_appeal(%L,false,%L,%L)',cs,'appeal-reserve','Attempt to refund the same units twice'),'PT409'),'appeal refund cannot replay';
  assert (public.trust_release(a)->>'released_units')::bigint=60,'clean mature exposure released';
  assert (public.trust_release(a)->>'released_units')::bigint=0,'release retry idempotent';
  perform public.claim_task(a,solo);
  assert (select count(*)=2 from public.trust_escrows where agent_id=a),'clean released capacity reusable for a new task';
  -- Chain continuity, exact UTF-8 bytes, pagination and immutability.
  original:=repeat('0',64); n:=0;
  for r in select * from public.trust_events where agent_id=a order by sequence loop
    n:=n+1;
    assert r.sequence=n and r.previous_hash=original,'history has no gaps';
    assert r.hash=encode(extensions.digest(convert_to(r.canonical,'UTF8'),'sha256'),'hex'),'event canonical bytes verify';
    original:=r.hash;
  end loop;
  assert public.trust_account_view(a,1,0)->>'head'=original,'portable head is explicit';
  assert jsonb_array_length(public.trust_account_view(a,1,0)->'events')=1,'history pages bounded';
  assert pg_temp.p15_fails(format('delete from public.trust_events where agent_id=%L',a),'PT403'),'history cannot be erased';
  -- Withholding or replacement can restart only through the labelled attested reserve.
  update public.missions set status='active' where id=m;
  t2:=public.insert_task_from_json(m,'{"key":"recovery","title":"Sealed recovery","kind":"analysis","capabilities":["analysis"],"ensemble":{"distinct_labs":false,"roles":[{"role":"proposer"},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  perform public.bind_trust_task(t2);
  perform public.credit_trust_test_units(a,100,'p15-receipt-a2','local-auditor');
  perform public.trust_release(b); perform public.trust_release(c);
  select id into e from public.ensembles where task_id=t2;
  ma:=(public.ensemble_join(a,e,'proposer')->>'id')::uuid;
  perform public.ensemble_join(b,e,'critic'); perform public.ensemble_join(c,e,'synthesizer');
  perform public.ensemble_commit(a,e,1,public.sealed_text_digest(e,1,ma,'draft','Recovery draft','Preserve this evidence',nonce));
  assert pg_temp.p15_fails(format('select public.recover_sealed_round(%L,1,%L,%L)',e,'local-reserve','Premature reset without liveness evidence'),'PT409'),'cannot grind an intact sealed roster';
  perform public.ensemble_leave(b,e,'Leave a sealed roster before disclosure');
  j:=public.recover_sealed_round(e,1,'local-reserve','A departed critic invalidated the committed roster');
  assert (select round=2 from public.ensembles where id=e),'auditable recovery advances round';
  assert (select count(*)=1 from public.ensemble_commitments where ensemble_id=e and round=1),'recovery preserves old commitments';
  assert jsonb_array_length(public.ensemble_view(e)->'recoveries')=1,'Phase 13 recovery review path preserved';
  assert pg_temp.p15_fails(format('select public.recover_sealed_round(%L,1,%L,%L)',e,'local-reserve','Attempt a stale sealed restart'),'PT409'),'recovery expected-round guard';
  assert not has_function_privilege('anon','public.trust_enroll(uuid)','EXECUTE'),'anonymous cannot impersonate enrollment';
  assert not has_function_privilege('authenticated','public.credit_trust_test_units(uuid,bigint,text,text)','EXECUTE'),'browser cannot credit stake';
  assert not has_function_privilege('posterity_orchestrator','public.decide_trust_case(uuid,boolean,bigint,text,text)','EXECUTE'),'matcher cannot adjudicate';
  assert not has_function_privilege('authenticated','public.ensemble_reveal(uuid,uuid,integer,text,text,text,text)','EXECUTE'),'browser cannot impersonate reveal';
  assert not has_table_privilege('service_role','public.trust_events','INSERT'),'even API writes go through chained entry points';
  assert not has_table_privilege('anon','public.trust_accounts','SELECT'),'raw stake accounts private to guarded API';
  raise notice 'PHASE15: epochs, opt-in escrow, bounded rewards, commit/reveal, evidence, appeals, recovery and history passed';
end $$;
rollback;
